-- Synthetic fixtures: no person/account/page is seeded in production.
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
create function public.sales_test_payload(p_id integer,p_contact text default '0907000401') returns jsonb language sql as $$
 select jsonb_build_object('request_id','00000000-0000-4000-8000-'||lpad(p_id::text,12,'0'),'name','Visitor '||p_id,'business','Input café '||p_id,'contact',p_contact,
 'intent','sample','note','Visitor-input note only','source','website','medium','referral','campaign','event_contact_v1','consent',true,'partner_consent',true,
 'throttle_key',repeat('a',64),'previous_throttle_key',repeat('b',64),'location','Test region','product_interest','Hồng trà OP1','tea_ids',jsonb_build_array('black-op1'),'requested_quantity_kg',2.125,'desired_date','2027-01-15')
$$;
create function public.sales_test_manage_page(p_partner_id uuid,p_input jsonb) returns jsonb language sql as $$
 select public.partner_network_manage_sales_page(p_partner_id,p_input||jsonb_build_object('expected_revision',coalesce((select revision from public.partner_network_sales_pages where partner_id=p_partner_id),0)))
$$;
set role authenticated;
select public.test_assert((select count(*)=0 from public.partner_network_sales_pages),'no automatic personal page creation');
select public.test_error(format('select public.sales_test_manage_page(%L,''{"slug":"bad--slug","display_name":"Test","phone":"0901000001","region":"Test","tea_ids":["black-op1"],"reason":"Reviewed"}'')',current_setting('test.partner_a')),'invalid_sales_page');
select public.test_error(format('select public.sales_test_manage_page(%L,''{"slug":"test-missing","phone":"0901000001","region":"Test","tea_ids":["black-op1"],"reason":"Reviewed"}'')',current_setting('test.partner_a')),'invalid_sales_page');
select public.test_error(format('select public.sales_test_manage_page(%L,''{"slug":"test-wrong","display_name":"Test","phone":"+00901000001","region":"Test","tea_ids":["black-op1"],"reason":"Reviewed"}'')',current_setting('test.partner_a')),'invalid_sales_page');
select public.test_error(format('select public.sales_test_manage_page(%L,''{"slug":"test-wrong","display_name":"Test","phone":"0901000001","region":"Test","tea_ids":["black-op1"],"published":"true","reason":"Reviewed"}'')',current_setting('test.partner_a')),'invalid_sales_page');
select public.sales_test_manage_page(current_setting('test.partner_a')::uuid,'{"slug":"test-partner-a","display_name":"Test Partner A","phone":"0901000001","region":"Test region","tea_ids":["black-op1","smoked-black"],"published":false,"reason":"Reviewed test-only public details"}');
select public.test_assert(public.partner_network_public_sales_page('test-partner-a') is null,'draft page is not public');
select public.test_error(format('select public.sales_test_manage_page(%L,''{"published":true,"reason":"Review missing"}'')',current_setting('test.partner_a')),'sales_page_content_review_required');
select public.sales_test_manage_page(current_setting('test.partner_a')::uuid,'{"published":true,"content_reviewed":true,"reason":"Explicitly reviewed public name and phone"}');
select public.sales_test_manage_page(current_setting('test.partner_b')::uuid,'{"slug":"test-partner-b","display_name":"Test Partner B","phone":"0901000002","region":"Test region","tea_ids":["black-op1"],"published":true,"content_reviewed":true,"reason":"Explicitly reviewed B public details"}');
select set_config('test.page_a_revision',(select revision::text from public.partner_network_sales_pages where partner_id=current_setting('test.partner_a')::uuid),false);
select public.sales_test_manage_page(current_setting('test.partner_a')::uuid,'{"published":true,"content_reviewed":true,"reason":"No content change"}');
select public.test_error(format('select public.sales_test_manage_page(%L,''{"slug":"renamed-partner-a","reason":"Published links must stay stable"}'')',current_setting('test.partner_a')),'sales_page_slug_locked');
select public.test_assert((select revision::text=current_setting('test.page_a_revision') from public.partner_network_sales_pages where partner_id=current_setting('test.partner_a')::uuid),'no-op review does not invalidate published revision');
set role anon;
select public.test_assert((select count(*)=6 from jsonb_object_keys(public.partner_network_public_sales_page('test-partner-a'))) and not(public.partner_network_public_sales_page('test-partner-a') ?| array['id','partner_id','email']),'anonymous page DTO exposes only six approved public fields');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-a',1,public.sales_test_payload(401))$q$,'permission denied');
reset role;
select public.test_error(format('update public.partner_network_sales_pages set partner_id=%L where slug=''test-partner-a''',current_setting('test.partner_b')),'sales_page_owner_immutable');
insert into public.trade_opportunities(id,contact_key,business_name,contact,stage,monthly_potential_kg,notes)
 values('journey-preexisting-central','0907000401','PRIVATE_EXISTING_CLIENT','0907000401','quoted',999,'INTERNAL_CRM_SECRET');
set role service_role;
select set_config('request.jwt.claim.role','service_role',false);
select set_config('request.jwt.claim.sub','',false);
select public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(401));
select public.test_assert((select status='pending' and opportunity_id is null and requested_quantity_kg=2.125 and expected_volume_kg is null and requested_delivery_on='2027-01-15' from public.partner_network_referrals where id='00000000-0000-4000-8000-000000000401'),'inbound pending referral keeps one-time quantity/date separate from monthly volume');
select public.test_assert((select r.created_at=e.received_at and r.source_enquiry_id=e.id and r.partner_consent_at=e.consent_at from public.partner_network_referrals r join public.event_enquiries e on e.id=r.id where r.id='00000000-0000-4000-8000-000000000401'),'trusted receipt time and explicit consent bind immutable origin');
select public.test_assert((select count(*)=1 from public.trade_opportunities where contact_key='0907000401'),'inbound creates exactly one central CRM relationship');
select public.test_assert((select business_name='PRIVATE_EXISTING_CLIENT' and stage='quoted' and monthly_potential_kg=999 from public.trade_opportunities where id='journey-preexisting-central'),'existing customer identity stage and monthly potential are not overwritten by visitor input');
select public.test_assert((public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(401)||jsonb_build_object('throttle_key',repeat('c',64)))->>'is_new')::boolean=false,'same request retry on another network is idempotent');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(401)||'{"requested_quantity_kg":3}'::jsonb)$q$,'page_enquiry_retry_conflict');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-b',1,public.sales_test_payload(401))$q$,'page_enquiry_retry_conflict');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(403)||'{"partner_consent":false}'::jsonb)$q$,'partner_consent_required');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(403)||'{"consent":false}'::jsonb)$q$,'invalid_event_enquiry');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(403)||'{"tea_ids":["steamed-green"]}'::jsonb)$q$,'invalid_page_tea_selection');
select public.test_error($q$select public.partner_network_submit_page_enquiry('test-partner-a',current_setting('test.page_a_revision')::integer,public.sales_test_payload(403)||'{"tea_ids":["black-op1","black-op1"]}'::jsonb)$q$,'invalid_page_tea_selection');
select public.test_assert(not exists(select 1 from public.event_enquiries where id='00000000-0000-4000-8000-000000000403') and not exists(select 1 from public.partner_network_referrals where id='00000000-0000-4000-8000-000000000403'),'invalid intake cannot leave partial enquiry or referral');
select public.partner_network_submit_page_enquiry('test-partner-b',1,public.sales_test_payload(402));
select public.test_assert((select count(*)=1 from public.trade_opportunities where contact_key='0907000401'),'another page duplicate reuses central CRM rather than creating a second account');
reset role;
update public.trade_opportunities set notes='INTERNAL_CRM_SECRET',stage='sample_sent' where contact_key='0907000401';
insert into public.sample_requests(id,opportunity_id,status,sent_at,phone,address,note) select 'journey-sample',id,'sent',clock_timestamp(),'PRIVATE_PHONE','PRIVATE_ADDRESS','PRIVATE_SAMPLE_NOTE' from public.trade_opportunities where contact_key='0907000401';
insert into public.trade_quotes(id,opportunity_id,status,sent_at,note,total) select 'journey-quote',id,'sent',clock_timestamp(),'PRIVATE_QUOTE_NOTE',9999999 from public.trade_opportunities where contact_key='0907000401';
set role authenticated;
select set_config('request.jwt.claim.role','authenticated',false);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((select x->'pipeline_stage'='null'::jsonb and jsonb_array_length(x->'samples')=0 and jsonb_array_length(x->'quotes')=0 from jsonb_array_elements(public.partner_network_snapshot()->'referrals')x where x->>'id'='00000000-0000-4000-8000-000000000401'),'pending origin cannot expose existing customer sample/quote/pipeline history');
select public.test_assert((select count(*)=0 from public.partner_network_sales_pages),'partner cannot bypass public projection via table reads');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.test_error($q$select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000401','accept','{}')$q$,'duplicate_resolution_required');
select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000401','accept','{"reason":"Origin and central CRM reuse explicitly reviewed"}');
select public.test_assert((select r.opportunity_id=e.opportunity_id from public.partner_network_referrals r join public.event_enquiries e on e.id=r.source_enquiry_id where r.id='00000000-0000-4000-8000-000000000401'),'manager acceptance reuses saved central opportunity');
select public.test_error($q$select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000402','accept','{"reason":"Competing duplicate reviewed"}')$q$,'opportunity_already_attributed');
select public.partner_network_resolve_lead('00000000-0000-4000-8000-000000000402','reject','{"reason":"Duplicate with established origin from A"}');
reset role;
select public.test_error($q$update public.partner_network_referrals set partner_consent_version='changed' where id='00000000-0000-4000-8000-000000000401'$q$,'sales_origin_immutable');
insert into public.orders(id,ts,type,status,stage,health,quote_id,customer_name,address,note,tracking_token,lines,shipping_carrier,tracking_code,carrier_status_name)
 values('journey-owned-order',clock_timestamp(),'wholesale','shipped','shipping','ok','journey-quote','PRIVATE_ORDER_NAME','PRIVATE_ORDER_ADDRESS','PRIVATE_ORDER_NOTE','PRIVATE_TRACKING_TOKEN',
 '[{"name":"Public Tea","qty":2.125,"unit":"kg","price":90000,"cost":60000,"internal_note":"PRIVATE_LINE_NOTE"}]','vietnam_post','TEST-TRACKING','In transit');
insert into public.orders(id,ts,type,status,quote_id,customer_name) select 'journey-historical-order',received_at-interval '1 day','wholesale','completed','journey-quote','Private old customer' from public.event_enquiries where id='00000000-0000-4000-8000-000000000401';
insert into public.procedure_runs(order_id,delivery_due_at,next_action) values('journey-owned-order','2027-01-16 08:00:00Z','PRIVATE_PROCEDURE_ACTION');
insert into public.order_events(order_id,created_at,actor,message) values('journey-owned-order',clock_timestamp()+interval '1 hour','PRIVATE_EVENT_ACTOR','PRIVATE_EVENT_MESSAGE');
select set_config('test.journey_event_timestamp',(select max(created_at)::text from public.order_events where order_id='journey-owned-order'),false);
insert into public.receivables values('journey-recv','journey-owned-order',1000000,1000000,'paid');
insert into public.receivable_payments(id,receivable_id,amount) values('journey-cash','journey-recv',1000000);
select public.test_assert(not exists(select 1 from public.partner_network_order_links where order_id='journey-historical-order'),'receipt timestamp excludes pre-intake orders from automatic credit');
set role authenticated;
select public.test_assert((select r.status='accepted' from public.partner_network_referrals r join public.partner_network_order_links l on l.referral_id=r.id where l.order_id='journey-owned-order'),'real new quote-linked order automatically reaches accepted referral');
select public.test_error($q$select public.partner_network_order_partner_update('journey-owned-order','{"forecast_amount":10.5,"reason":"Invalid fractional currency"}')$q$,'invalid_partner_order_update');
select public.test_error($q$select public.partner_network_order_partner_update('journey-owned-order','{"forecast_amount":5000}')$q$,'reason_required');
select public.partner_network_order_partner_update('journey-owned-order','{"forecast_amount":5000,"forecast_note":"Manual estimate until costs confirmed","expected_payment_on":"2027-01-22","public_note":"Planned dispatch confirmed","next_action":"Check tea after arrival","reason":"Explicit manual expectation communicated"}');
select public.test_assert(not exists(select 1 from public.partner_network_commissions where order_id='journey-owned-order'),'manual forecast does not create approval or a payout');
select public.test_assert(exists(select 1 from public.partner_network_audit where entity='partner_network_order_links' and entity_id='journey-owned-order' and after_data->>'update_reason'='Explicit manual expectation communicated'),'manual forecast update captures accountable audit reason');
select public.test_assert((select bool_and(expected_payment_on is null) from public.partner_network_order_links where order_id<>'journey-owned-order'),'ETA is never invented for other orders');
select set_config('test.journey_paid_before',(select to_jsonb(c)::text from public.partner_network_commissions c where order_id='test-o1'),false);
select public.partner_network_order_partner_update('test-o1','{"forecast_amount":100,"forecast_note":"Separate manual estimate metadata","reason":"Test that metadata cannot rewrite paid commission"}');
select public.test_assert((select to_jsonb(c)=current_setting('test.journey_paid_before')::jsonb from public.partner_network_commissions c where order_id='test-o1'),'forecast metadata never rewrites historical paid commission');
select public.partner_network_reconcile('journey-owned-order','{"vat_amount":0,"billed_shipping_amount":0,"refunded_amount":0,"internal_cost_total":500000,"minimum_retained_profit":100000,"review_note":"Costs reviewed only for genuine order"}');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.test_assert((select x->>'tracking_code'='TEST-TRACKING' and (x->>'delivery_due_at')::timestamptz='2027-01-16 08:00:00Z'::timestamptz and x->>'expected_payment_on'='2027-01-22' and (x->>'forecast_amount')::numeric=5000 and (x->>'collection_complete')::boolean from jsonb_array_elements(public.partner_network_snapshot()->'orders')x where x->>'id'='journey-owned-order'),'own accepted order exposes only real tracking/planned delivery/manual commission ETA');
select public.test_assert((select jsonb_array_length(x->'samples')=1 and jsonb_array_length(x->'quotes')=1 from jsonb_array_elements(public.partner_network_snapshot()->'referrals')x where x->>'id'='00000000-0000-4000-8000-000000000401'),'accepted referral can follow safe sample and quote states');
select public.test_assert((select (x->>'updated_at')::timestamptz=current_setting('test.journey_event_timestamp')::timestamptz from jsonb_array_elements(public.partner_network_snapshot()->'orders')x where x->>'id'='journey-owned-order'),'actual order event advances safe updated timestamp without exposing event contents');
select public.test_assert(public.partner_network_snapshot()::text !~ 'PRIVATE_|INTERNAL_CRM_SECRET','own projection excludes addresses, staff notes, tokens, line prices/costs and procedure staff actions');
select public.test_assert((select (x->'lines'->0) ?& array['name','qty','unit'] and not(x->'lines'->0 ?| array['price','cost','internal_note']) from jsonb_array_elements(public.partner_network_snapshot()->'orders')x where x->>'id'='journey-owned-order'),'order lines are whitelisted to public name quantity unit');
select public.test_assert((select x->'eligible_amount'='null'::jsonb and (x->>'paid_amount')::numeric=82500 from jsonb_array_elements(public.partner_network_snapshot()->'commissions')x where x->>'order_id'='test-o1'),'stale entitlement is unknown while historical paid amount stays visible');
select public.test_assert((select x->>'expected_payment_on'='2027-01-22' from jsonb_array_elements(public.partner_network_snapshot()->'commissions')x where x->>'order_id'='journey-owned-order'),'commission follows explicit order ETA without automatic payout promise');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',false);
select public.test_assert(not exists(select 1 from jsonb_array_elements(public.partner_network_snapshot()->'orders')x where x->>'id'='journey-owned-order'),'other partner cannot read owned order');
select public.test_assert((select x->>'status'='rejected' and jsonb_array_length(x->'samples')=0 and jsonb_array_length(x->'quotes')=0 from jsonb_array_elements(public.partner_network_snapshot()->'referrals')x where x->>'id'='00000000-0000-4000-8000-000000000402'),'rejected duplicate retains its own submitted data without commercial history');
